 "content": "def transform(grid):
    """Copy the interior occupancy of a patterned rectangular frame into
    empty rectangular frames having the same bounding-box dimensions."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    colors = {v for row in grid for v in row if v != 0}
    objs = []
    for color in colors:
        pts = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == color}
        while pts:
            seed = pts.pop(); comp = {seed}; stack = [seed]
            while stack:
                r, c = stack.pop()
                for q in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                    if q in pts:
                        pts.remove(q); comp.add(q); stack.append(q)
            rs = [p[0] for p in comp]; cs = [p[1] for p in comp]
            r0,r1,c0,c1 = min(rs),max(rs),min(cs),max(cs)
            if r1-r0 < 2 or c1-c0 < 2:
                continue
            border = {(r,c) for r in range(r0,r1+1) for c in range(c0,c1+1)
                      if r in (r0,r1) or c in (c0,c1)}
            if not border <= comp:
                continue
            interior = {(r,c) for r in range(r0+1,r1) for c in range(c0+1,c1)}
            filled = comp & interior
            objs.append((color,r0,r1,c0,c1,filled))
    donors = [o for o in objs if o[5]]
    for donor in donors:
        color, r0,r1,c0,c1,filled = donor
        dh,dw = r1-r0+1,c1-c0+1
        for target in objs:
            tc,tr0,tr1,tc0,tc1,tfilled = target
            if tc == color or tr1-tr0+1 != dh or tc1-tc0+1 != dw or tfilled:
                continue
            # Copy the donor's relative interior pattern, recolored to target.
            for r in range(tr0+1,tr1):
                for c in range(tc0+1,tc1):
                    out[r][c] = tc if (r-r0,c-c0) in {(a-r0,b-c0) for a,b in filled} else 0
    return out
