    colors = {v for row in grid for v in row if v != 0}
    objs = []
    # A frame's interior motif can be disconnected from its border, so find
    # each colored frame from its complete color footprint, not components.
    for color in colors:
        pts = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == color}
        if not pts:
            continue
        rs = [p[0] for p in pts]; cs = [p[1] for p in pts]
        r0,r1,c0,c1 = min(rs),max(rs),min(cs),max(cs)
        if r1-r0 < 2 or c1-c0 < 2:
            continue
        border = {(r,c) for r in range(r0,r1+1) for c in range(c0,c1+1)
                  if r in (r0,r1) or c in (c0,c1)}
        if not border <= pts:
            continue
        interior = {(r,c) for r in range(r0+1,r1) for c in range(c0+1,c1)}
        filled = pts & interior
        objs.append((color,r0,r1,c0,c1,filled))
    donors = [o for o in objs if o[5]]
    targets = [o for o in objs if not o[5]]
    # The motif is the frame with the greatest interior occupancy; it is
    # copied into each other complete frame, whose own color is retained.
    if donors:
        donors = [max(donors, key=lambda o: len(o[5]))]
    for donor in donors:
        color, r0,r1,c0,c1,filled = donor
        dh,dw = r1-r0+1,c1-c0+1
        for target in targets:
