            if tc == color or tr1-tr0+1 != dh or tc1-tc0+1 != dw:
                continue
            # Copy donor occupancy, preserving target border and source.
            donor_pattern = {(a-r0,b-c0) for a,b in filled}
            for r in range(tr0+1,tr1):
                for c in range(tc0+1,tc1):
                    out[r][c] = tc if (r-tr0,c-tc0) in donor_pattern else 0
    return out", "exit_code": 0, "error": null}

